from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import CustomerSubscription
from .serializers import SubscriptionSerializer
from .permissions import IsSubscriptionOwner

class SubscriptionViewSet(viewsets.ModelViewSet):
    serializer_class = SubscriptionSerializer

    def get_queryset(self):
        return CustomerSubscription.objects.filter(customer=self.request.user)

    def get_permissions(self):
        if self.action in ['update', 'partial_update', 'downgrade']:
            return [permissions.IsAuthenticated(), IsSubscriptionOwner()]
        elif self.action == 'destroy':
            return [permissions.IsAdminUser()]
        return [permissions.IsAuthenticated()]

    @action(detail=True, methods=['post'])
    def downgrade(self, request, pk=None):
        subscription = self.get_object()
        subscription.tier = 'free_tier'
        subscription.save(update_fields=['tier'])
        return Response({'status': 'downgraded to free tier'})
